#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>

// CLI tool that processes user session records from DynamoDB
// and generates access reports. Reads JSON-like input from stdin.

typedef struct session_record {
    char *user_id;
    char *action;
    char *resource_arn;
    int ref_count;
    struct session_record *next;
} session_record_t;

typedef struct {
    session_record_t *head;
    session_record_t *current;
    int count;
} record_list_t;

static record_list_t g_records = {0};
static session_record_t *g_cached_record = NULL;

session_record_t *create_record(const char *user_id, const char *action, const char *resource) {
    session_record_t *rec = (session_record_t *)malloc(sizeof(session_record_t));
    if (!rec) return NULL;
    rec->user_id = strdup(user_id);
    rec->action = strdup(action);
    rec->resource_arn = strdup(resource);
    rec->ref_count = 1;
    rec->next = NULL;
    return rec;
}

void free_record(session_record_t *rec) {
    if (!rec) return;
    rec->ref_count--;
    if (rec->ref_count <= 0) {
        free(rec->user_id);
        free(rec->action);
        free(rec->resource_arn);
        free(rec);
    }
}

void add_record(record_list_t *list, session_record_t *rec) {
    rec->next = list->head;
    list->head = rec;
    list->count++;
}

// Process a "REVOKE" command - removes record but caches pointer for audit log
void process_revoke(record_list_t *list, const char *target_user) {
    session_record_t *prev = NULL;
    session_record_t *curr = list->head;

    while (curr) {
        if (strcmp(curr->user_id, target_user) == 0) {
            // Cache for deferred audit write-back to DynamoDB
            g_cached_record = curr;  // BUG: dangling pointer after free

            if (prev) prev->next = curr->next;
            else list->head = curr->next;

            list->count--;
            free_record(curr);  // Freed here, but g_cached_record still points to it
            return;
        }
        prev = curr;
        curr = curr->next;
    }
}

// Flush audit uses the cached (now-freed) record
void flush_audit_log() {
    if (g_cached_record) {
        // USE-AFTER-FREE: accessing freed memory
        // An attacker controlling input can spray the heap to control
        // what g_cached_record->resource_arn points to
        printf("AUDIT: user=%s action=%s resource=%s\n",
               g_cached_record->user_id,
               g_cached_record->action,
               g_cached_record->resource_arn);
        g_cached_record = NULL;
    }
}

void process_input(char *line) {
    char cmd[32], arg1[256], arg2[256], arg3[256];

    if (sscanf(line, "ADD %255s %255s %255s", arg1, arg2, arg3) == 3) {
        session_record_t *rec = create_record(arg1, arg2, arg3);
        if (rec) add_record(&g_records, rec);
    } else if (sscanf(line, "REVOKE %255s", arg1) == 1) {
        process_revoke(&g_records, arg1);
    } else if (strncmp(line, "FLUSH", 5) == 0) {
        flush_audit_log();
    } else if (sscanf(line, "SPRAY %255s", arg1) == 1) {
        // Heap spray: allocate many same-sized chunks to reclaim freed memory
        for (int i = 0; i < 100; i++) {
            char *spray = malloc(sizeof(session_record_t));
            if (spray) memset(spray, 0x41, sizeof(session_record_t));
        }
    }
}

int main(int argc, char *argv[]) {
    char line[1024];

    printf("Session Record Processor v2.3.1\n");
    printf("Reading from DynamoDB export stream...\n");

    while (fgets(line, sizeof(line), stdin)) {
        line[strcspn(line, "\n")] = 0;
        if (strlen(line) == 0) continue;
        if (strcmp(line, "EXIT") == 0) break;
        process_input(line);
    }

    // Final flush on exit
    flush_audit_log();

    // Cleanup
    session_record_t *curr = g_records.head;
    while (curr) {
        session_record_t *next = curr->next;
        free_record(curr);
        curr = next;
    }

    return 0;
}
